package main

import (
	"encoding/json"
	"fmt"
	"strings"
	"unicode"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

func main() {
	base := `"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[]`

	// 1) Literal U+0085 in the member NAME (raw bytes in the JSON document).
	lit := "{" + base + `,"meta` + "\u0085" + `info":{"x":1,"x":2}}`
	_, err1 := darksafe.ParseReleaseInput([]byte(lit))
	fmt.Println("LITERAL U+0085 name, dup:", err1)

	// 2) The same name written via the JSON escape spelling.
	esc := "{" + base + `,"meta\u0085info":{"x":1,"x":2}}`
	_, err2 := darksafe.ParseReleaseInput([]byte(esc))
	fmt.Println("ESCAPED spelling dup  :", err2)

	// Paths must be IDENTICAL regardless of spelling.
	p := func(e error) string {
		s := e.Error()
		i := strings.Index(s, "$")
		return s[i:]
	}
	fmt.Println("paths identical:", p(err1) == p(err2), "->", p(err1))

	// 3) note value errors point at .note under the bracketed object.
	noteBad := "{" + base + `,"meta` + "\u0085" + `info":{"note":"` + "\xff" + `"}}`
	_, err3 := darksafe.ParseReleaseInput([]byte(noteBad))
	fmt.Println("note bad utf8         :", err3)
	noteSur := "{" + base + `,"meta` + "\u0085" + `info":{"note":"\uD800"}}`
	_, err4 := darksafe.ParseReleaseInput([]byte(noteSur))
	fmt.Println("note surrogate        :", err4)

	// 4) Illegal text IN THE NAME points at the owning object ($).
	keyBad := "{" + base + `,"me` + "\xff" + `ta":1}`
	_, err5 := darksafe.ParseReleaseInput([]byte(keyBad))
	fmt.Println("bad utf8 in name      :", err5)

	// 5) Raw control must NOT appear, but literal backslash-u-0085 TEXT (a
	//    name containing the 8 chars \ u 0 0 8 5) is a DIFFERENT member name.
	litText := "{" + base + `,"meta\\u0085info":{"x":1,"x":2}}` // \\ -> a real backslash
	_, err6 := darksafe.ParseReleaseInput([]byte(litText))
	fmt.Println("literal \\u0085 TEXT dup:", err6)

	// 6) Every quoted fragment decodes back; no raw control anywhere.
	for _, e := range []error{err1, err2, err3, err4, err5, err6} {
		m := e.Error()
		for _, r := range m {
			if (unicode.IsControl(r) || r == 0x2028 || r == 0x2029) && r != '\n' {
				fmt.Printf("  !! RAW CONTROL %#U in %q\n", r, m)
			}
		}
		// extract ["..."] segments and JSON-decode each
		rest := m
		for {
			o := strings.Index(rest, "[\"")
			if o < 0 {
				break
			}
			j := o + 2
			for j < len(rest) {
				if rest[j] == '\\' {
					j += 2
					continue
				}
				if rest[j] == '"' {
					break
				}
				j++
			}
			var dec string
			tok := rest[o+1 : j+1]
			if err := json.Unmarshal([]byte(tok), &dec); err != nil {
				fmt.Println("  !! segment not decodable JSON:", tok, err)
			}
			rest = rest[j+1:]
		}
	}
	fmt.Println("decode + no-control checks done")
}
EOF
