package main

import (
	"encoding/json"
	"fmt"
	"strings"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

func main() {
	base := `"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[]`

	// Duplicated FIELD name contains a literal DEL and a C1 control.
	doc := "{" + base + `,"k` + "\x7f" + `x` + "\u0085" + `":1,` +
		`"k` + "\x7f" + `x` + "\u0085" + `":2}`
	_, err := darksafe.ParseReleaseInput([]byte(doc))
	fmt.Println("field with literal controls:", err)

	// Same duplicated name written entirely via \uXXXX escapes.
	doc2 := "{" + base + `,"k\u007fx\u0085":1,"k\u007fx\u0085":2}`
	_, err2 := darksafe.ParseReleaseInput([]byte(doc2))
	fmt.Println("field via escapes         :", err2)
	fmt.Println("messages identical:", err.Error() == err2.Error())

	// The field token must be decodable JSON (no \xNN). Extract 字段 "..." 
	for _, e := range []error{err, err2} {
		m := e.Error()
		i := strings.Index(m, "字段 ")
		tok := m[i+len("字段 "):]
		q := strings.Index(tok, `"`)
		end := strings.LastIndex(tok, `"`)
		lit := tok[q : end+1]
		var s string
		if jerr := json.Unmarshal([]byte(lit), &s); jerr != nil {
			fmt.Println("  !! field token not JSON-decodable:", lit, jerr)
		} else {
			fmt.Printf("  field token decodes to %q OK\n", s)
		}
	}

	// Fallback (encoding/json) walk: a duplicate seen before malformation,
	// where an ancestor name contains a C1 control. Object never closes.
	doc3 := "{" + base + `,"meta` + "\u0085" + `info":{"x":1,"x":2}`
	_, err3 := darksafe.ParseReleaseInput([]byte(doc3))
	fmt.Println("fallback malformed + dup  :", err3)
}
