// quotedJSONStrings scans msg for JSON string literals ("...", honoring
// backslash escapes) and returns the position and decoded value of each. It
// is used to prove every quoted fragment of a rendered location is decodable
// JSON rather than Go %q text such as "\x7f".
func quotedJSONStrings(t *testing.T, msg string) []string {
	t.Helper()
	var decoded []string
	for i := 0; i < len(msg); i++ {
		if msg[i] != '"' {
			continue
		}
		j := i + 1
		for j < len(msg) {
			switch msg[j] {
			case '\\':
				j += 2
				continue
			case '"':
				var s string
				lit := msg[i : j+1]
				if err := json.Unmarshal([]byte(lit), &s); err != nil {
					t.Fatalf("fragment %q in message %q is not decodable JSON: %v", lit, msg, err)
				}
				decoded = append(decoded, s)
				i = j
				j = len(msg)
			default:
				j++
			}
		}
	}
	return decoded
}

